import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: empty and single items (base premiums + fee) ---
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });
  it("single sword (plain, new customer) → 100 G base + 10 G first insurance + 5 G fee = 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it.todo("single amulet (plain, new customer) → 60 G base + 6 G first insurance + 5 G fee = 71 G");
  it.todo("single staff (plain, new customer) → 80 G base + 8 G first insurance + 5 G fee = 93 G");
  it.todo("single potion (plain, new customer) → 40 G base + 4 G first insurance + 5 G fee = 49 G");
  it.todo("single rune (component) → 25 G base + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");

  // --- Building block of 3 alike components ---
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");

  // --- "Alike" components means same type ---
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("cursed sword adds 50 % of that item's base premium (100 G → +50 G)");
  it.todo("sword with enchantment 5 adds 30 % high-enchantment surcharge (100 G → +30 G)");
  it.todo("sword with enchantment 4 has no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 gets both surcharges (+50 G and +30 G)");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword + plain amulet → policy base 160 G, curse adds 50 G (not 50 % of policy total) → 210 G before further modifiers and fee");

  // --- Policy-wide modifiers ---
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount on the policy base premium");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first insurance surcharge of 10 % applies to every quote's items");
  it.todo("second quote in a scenario receives a 15 % follow-up contract discount");

  // --- Rounding in MHPCO's favour ---
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");

  // --- Integration examples ---
  it.todo("newcomer (0 years) with a cursed steel sword enchantment 3 → premium 165 G");
  it.todo("3-year customer's second quote, cursed steel sword enchantment 7 → premium 160 G");

  // --- Claim: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");

  // --- Claim: special clauses ---
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins over dragon material)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack damaging sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)");

  // --- Claim: cap ---
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a cursed sword → cap 2000 G based on the unmodified insurance value");
  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount affects premium only)");
  it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword policy, second claim of 1500 G after the first → payout 600 G, remainingCap 0 G");

  // --- Multiple items of the same type ---
  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("two sword damage entries against a two-sword policy → each is a separate damage with its own deductible");
  it.todo("more damage entries of a type than insured (two sword damages, one sword insured) → the claim is rejected");

  // --- Error cases ---
  it.todo("quote with an unknown item type (broomstick) → error, no results");
  it.todo("claim damaging an amulet when only a sword is insured → error");
  it.todo("claim with a damage entry of an unknown item type → error");
  it.todo("claim with a damage entry amount of -200 → error");

  // --- CLI ---
  it.todo("CLI reads a scenario from stdin and writes {results:[...]} to stdout");
  it.todo("CLI exits with a non-zero status code and writes to stderr on an invalid scenario");
});

