const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
};

export type ScenarioResult = { premium: number };

type Item = { type: string };

type Scenario = {
  steps: { items: Item[] }[];
};

export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
  const items = scenario.steps[0].items;
  const insuredItemsPremium = items.reduce(
    (total, item) =>
      total + BASE_PREMIUMS[item.type] * (1 + FIRST_INSURANCE_SURCHARGE_RATE),
    0,
  );
  const premium = Math.ceil(insuredItemsPremium + PROCESSING_FEE);
  return { results: [{ premium }] };
};

