const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

// Divides rather than multiplying by a rate: `amount * 1.1` introduces
// floating-point error that shifts the spec's round-up in MHPCO's favour.
const percentOf = (percent: number, amount: number): number => (amount * percent) / 100;

// MHPCO rounds every money amount in its own favour: premiums (customer pays)
// round up, payouts (MHPCO pays) round down.
const roundPremiumInMHPCOsFavour = Math.ceil;

export type ScenarioResult = { premium: number };

type Item = { type: string };

type Scenario = {
  steps: { items: Item[] }[];
};

const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];

export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
  const [quoteStep] = scenario.steps;
  const policyBasePremium = quoteStep.items.reduce(
    (total, item) => total + basePremiumForItem(item),
    0,
  );
  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
  const premium = roundPremiumInMHPCOsFavour(
    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  );
  return { results: [{ premium }] };
};

