const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const BLOCK_SIZE = 3;
const BLOCK_DISCOUNT_PERCENT = 20;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const PERCENT_WHOLE = 100;

// Divides rather than multiplying by a rate: `amount * 1.1` introduces
// floating-point error that shifts the spec's round-up in MHPCO's favour.
const percentOf = (percent: number, amount: number): number =>
  (amount * percent) / PERCENT_WHOLE;

// MHPCO rounds every money amount in its own favour: premiums (customer pays)
// round up, payouts (MHPCO pays) round down.
const roundPremiumInMHPCOsFavour = Math.ceil;

export type ScenarioResult = { premium: number };

// Items carry attributes no rule reads yet (material/enchantment/cursed drive
// the surcharge and claim tests still to come). They are typed as optional so
// the scenarios the tests actually send typecheck, without pricing them.
type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

type Step = { op: string; items: Item[] };

// `customer` and `op` are likewise unread so far: the loyalty-discount and
// follow-up-contract tests will reach for them.
type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
};

const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];

const sumBasePremiums = (items: Item[]): number =>
  items.reduce((total, item) => total + basePremiumForItem(item), 0);

const groupByType = (items: Item[]): Item[][] => {
  const groups = new Map<string, Item[]>();
  for (const item of items) {
    const group = groups.get(item.type) ?? [];
    group.push(item);
    groups.set(item.type, group);
  }
  return [...groups.values()];
};

// A block is a discount on the components' combined base premium, not a flat
// price: 3 runes are 75 G less 20 % = 60 G. Derived rather than hardcoded so the
// 20 % stays visible as the rule it is.
const blockBasePremium = (items: Item[]): number => {
  const undiscounted = sumBasePremiums(items);
  return undiscounted - percentOf(BLOCK_DISCOUNT_PERCENT, undiscounted);
};

// Exactly BLOCK_SIZE, not "at least": 4 or 7 runes form no block, so a bigger
// pile is never cheaper than the block it contains. Components only — three
// swords are three separate insurances, not a discounted building block.
const formsABlock = (alikeItems: Item[]): boolean =>
  alikeItems.length === BLOCK_SIZE && COMPONENT_TYPES.has(alikeItems[0].type);

const basePremiumForGroup = (alikeItems: Item[]): number =>
  formsABlock(alikeItems) ? blockBasePremium(alikeItems) : sumBasePremiums(alikeItems);

// Priced per group of alike items rather than over the whole list, so 3 runes
// and 3 moonstones each form their own block.
const policyBasePremiumFor = (items: Item[]): number =>
  groupByType(items)
    .map(basePremiumForGroup)
    .reduce((total, groupPremium) => total + groupPremium, 0);

const quoteFor = (items: Item[]): ScenarioResult => {
  const policyBasePremium = policyBasePremiumFor(items);
  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
  const premium = roundPremiumInMHPCOsFavour(
    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  );
  return { premium };
};

// Every scenario so far holds exactly one quote step, so only the first is
// priced. The follow-up-contract discount test will drive priced-per-step.
export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
  const [firstStep] = scenario.steps;
  return { results: [quoteFor(firstStep.items)] };
};

