  sum(items.map((item) => INSURANCE_VALUES[item.type]));

// MHPCO pays, so payouts round down.
const roundPayoutInMHPCOsFavour = Math.floor;

// Each damage entry carries its own deductible: one dragon attack damaging two
// items is two damages, and MHPCO withholds 100 G from each. The reimbursement
// clauses apply to the damage amount FIRST, so the deductible bites last.
const payoutForDamage = (damage: Damage, damagedItem: Item): number => {
  const reimbursable =
    (damagedItem.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_THRESHOLD
      ? percentOf(HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT, damage.amount)
      : damage.amount;
  return reimbursable - DEDUCTIBLE;
};

// The cap is a property of the POLICY, not of the claim: twice what the policy's
// items are insured for. Kept separate from the payout so the cross-claim
// accumulation the spec still demands has an obvious place to attach.
const capFor = (policy: QuoteStep): number =>
  insuranceSumFor(policy.items) * CAP_MULTIPLE;

const claimFor = (claim: ClaimStep, policy: QuoteStep): ClaimResult => {
  const payout = roundPayoutInMHPCOsFavour(
    sum(
      claim.incident.damages.map((damage) =>
        payoutForDamage(damage, damagedItemFor(damage, policy.items)),
      ),
    ),
  );
  return { payout, remainingCap: capFor(policy) - payout };
};

// `claim.policy` indexes the scenario's steps, and the referenced step must be a
// quote — a claim against a claim is meaningless. Nothing validates the scenario
// yet, so this states the assumption instead of casting past it; the
// error-case tests will turn the throw into a reported error.
const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep => {
  const step = steps[claim.policy];
  if (step === undefined || !isQuote(step)) {
    throw new Error(`Claim references step ${claim.policy}, which is not a quote`);
  }
  return step;
};

export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
  const results = scenario.steps.map((step, stepIndex) =>
    isQuote(step)
      ? quoteFor(
          step.items,
          scenario.customer,
          isFollowUpContract(scenario.steps.slice(0, stepIndex)),
        )
      : claimFor(step, policyReferencedBy(step, scenario.steps)),
  );
  return { results };
};

