// The cap is spent across every claim on a policy, not restored per claim, so
// the caller supplies what is left and a claim can be cut short by it.
const claimFor = (claim: ClaimStep, policy: QuoteStep, capRemaining: number): ClaimResult => {
  const desired = roundPayoutInMHPCOsFavour(
    sum(
      claim.incident.damages.map((damage) =>
        payoutForDamage(damage, damagedItemFor(damage, policy.items)),
      ),
    ),
  );
  const payout = Math.min(desired, capRemaining);
  return { payout, remainingCap: capRemaining - payout };
