// Which insured item a damage entry refers to, since the reimbursement clauses
// depend on that item's enchantment and material. Nothing validates that the
// policy actually covers the damaged type yet; the error-case tests will turn
// this throw into a reported error.
const damagedItemFor = (damage: Damage, insuredItems: Item[]): Item => {
  const item = insuredItems.find((insured) => insured.type === damage.itemType);
  if (item === undefined) {
    throw new Error(`Claim damages a ${damage.itemType}, which this policy does not cover`);
  }
  return item;
};

// The cap is a property of the POLICY, not of the claim: twice what the policy's
// items are insured for. Kept separate from the payout so the cross-claim
// accumulation the spec still demands has an obvious place to attach.
const capFor = (policy: QuoteStep): number =>
  insuranceSumFor(policy.items) * CAP_MULTIPLE;

// The cap is spent down across every claim on a policy rather than reset per
// claim, so the caller supplies what is left; a claim wanting more than remains
// is cut short by it.
const claimFor = (claim: ClaimStep, policy: QuoteStep, capRemaining: number): ClaimResult => {
  const desired = roundPayoutInMHPCOsFavour(
    sum(
      claim.incident.damages.map((damage) =>
        payoutForDamage(damage, damagedItemFor(damage, policy.items)),
      ),
    ),
  );
  const payout = Math.min(desired, capRemaining);
  return { payout, remainingCap: capRemaining - payout };
};

// `claim.policy` indexes the scenario's steps, and the referenced step must be a
// quote — a claim against a claim is meaningless. Nothing validates the scenario
// yet, so this states the assumption instead of casting past it; the
// error-case tests will turn the throw into a reported error.
const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep => {
  const step = steps[claim.policy];
  if (step === undefined || !isQuote(step)) {
    throw new Error(`Claim references step ${claim.policy}, which is not a quote`);
  }
  return step;
};

