// Only a rejected scenario is reported as a description and an exit code — the
// customer sent something MHPCO cannot price. Anything else is a fault in here,
// and is left to crash loudly rather than be dressed up as bad input.
const main = async (): Promise<void> => {
  const scenario = JSON.parse(await readStdin());
  try {
    process.stdout.write(JSON.stringify(runScenario(scenario)));
  } catch (error) {
    if (!(error instanceof InvalidScenarioError)) {
      throw error;
    }
    process.stderr.write(`${error.message}\n`);
    process.exitCode = REJECTED_EXIT_CODE;
  }
};

