2	
3	const REJECTED_EXIT_CODE = 1;
4	
5	const readStdin = async (): Promise<string> => {
6	  const chunks: string[] = [];
7	  process.stdin.setEncoding("utf8");
8	  for await (const chunk of process.stdin) {
9	    chunks.push(chunk as string);
10	  }
11	  return chunks.join("");
12	};
13	
14	// Stdin that is not JSON at all is the customer's input being wrong in the same
15	// way an unpriceable item type is, so it is reported the same way. Converting it
16	// here rather than widening the catch below keeps `InvalidScenarioError` meaning
17	// exactly one thing to the handler: the customer sent something MHPCO cannot
18	// price. A raw SyntaxError escaping as an unhandled rejection would print a
19	// stack trace through this module's internals.
20	// The assertion is the one place untrusted JSON becomes a Scenario, and it is
21	// deliberately not a validation: `runScenario` already rejects the parts it
22	// cannot price (unknown item types, claims on uninsured items) with the same
23	// error this reports, so re-checking the shape here would duplicate those rules
24	// in a second, weaker form. What this does guarantee is that the failure is a
25	// described rejection rather than a stack trace.
26	const parseScenario = (input: string): Scenario => {
27	  try {
28	    return JSON.parse(input) as Scenario;
29	  } catch (error) {
30	    throw new InvalidScenarioError(
31	      `Scenario is not valid JSON: ${(error as Error).message}`,
32	    );
33	  }
34	};
35	
36	// Only a rejected scenario is reported as a description and an exit code.
37	// Anything else is a fault in here, and is left to crash loudly rather than be
38	// dressed up as bad input — the whole pipeline sits in the `try` so that split
39	// is decided by the error's type, not by which line happened to throw.
40	const main = async (): Promise<void> => {
41	  try {
42	    const scenario = parseScenario(await readStdin());
43	    process.stdout.write(JSON.stringify(runScenario(scenario)));
44	  } catch (error) {
45	    if (!(error instanceof InvalidScenarioError)) {
46	      throw error;
47	    }
48	    process.stderr.write(`${error.message}\n`);
49	    process.exitCode = REJECTED_EXIT_CODE;
50	  }
